"""Enrollment tests use generated bytes, never real recordings or labels."""

import hashlib
import json

import pytest

from student_class_scales_train import argument_parser, contained, recordings


def write_rows(path, rows):
    path.write_text("\n".join(json.dumps(r) for r in rows))


def test_cross_corpus_holdouts_are_removed_before_any_audio_is_read(tmp_path):
    audio = tmp_path / "take.wav"
    audio.write_bytes(b"generated audio identity")
    checksum = hashlib.sha256(audio.read_bytes()).hexdigest()
    none = dict(id="none", speaker="none-speaker", split="train", kind="none", scored=True,
                events=[], non_errors=[], unsupported=[], wav=audio.name, ayahs=["1:1"])
    transcript = dict(speaker="transcribed-speaker", split="train", authorized=True,
                      verified=True, phones="بِسم", wav="other.wav")
    other = tmp_path / transcript["wav"]
    other.write_bytes(b"different generated identity")
    transcript["sha256"] = hashlib.sha256(other.read_bytes()).hexdigest()
    labels, enrolled = tmp_path / "help.jsonl", tmp_path / "transcribed.jsonl"
    write_rows(labels, [none, dict(none, id="held", speaker="held", wav="not-readable.wav")])
    write_rows(enrolled, [transcript, dict(transcript, speaker="held", split="eval", wav="also-missing.wav")])
    ref = dict(ayahs=[dict(s=1, a=1, p="بِسم")])
    rows, excluded = recordings(labels, enrolled, [], ref)
    assert {r["speaker"] for r in rows} == {"none-speaker", "transcribed-speaker"}
    assert excluded == ["held"]
    assert all(r["phones"] == "بِسم" for r in rows)
    assert rows[0]["audioSha256"] == checksum
    write_rows(enrolled, [dict(transcript, sha256="different"),
                          dict(transcript, speaker="held", split="eval", wav="also-missing.wav")])
    with pytest.raises(ValueError, match="audio identity"):
        recordings(labels, enrolled, [], ref)


def test_training_audio_cannot_escape_its_enrolled_corpus(tmp_path):
    with pytest.raises(ValueError, match="leaves"):
        contained(tmp_path, "../other.wav")


def test_prepare_and_fit_command_arguments_do_not_collide_with_standard_help():
    parser = argument_parser()
    args = parser.parse_args(["prepare", "--model", "/source", "--help-train", "/none.jsonl",
        "--transcribed", "/enrolled.jsonl", "--exclusions", "/excluded.json",
        "--augmentation", "/aug", "--config", "/config.json", "--out", "/cache"])
    assert args.command == "prepare"
    assert args.help_train == "/none.jsonl"
    fitted = parser.parse_args(["fit", "--prepared", "/cache", "--optimizer", "/optim.py", "--out", "/heads"])
    assert fitted.command == "fit"
    assert fitted.prepared == "/cache"
